async function processPendingAgentMessageAutoContinueTurns(opts: {
  droneId: string;
  chatName: string;
}): Promise<void> {
  const droneId = normalizeDroneIdentity(opts.droneId);
  const chatName = normalizeChatName(opts.chatName);
  if (!droneId || !chatName) return;
  const chatLockId = buildAgentMessageAutoContinueChatLockId({ droneId, chatName });
  if (!chatLockId || AGENT_MESSAGE_AUTO_CONTINUE_CHAT_IN_FLIGHT.has(chatLockId)) return;

  const stored = readChatFromStore({ droneId, chatName });
  const chatEntry = stored.available ? stored.chat : null;
  if (!chatEntry || !chatAgentMessageAutoContinueEnabled(chatEntry)) return;
  const turns: TranscriptTurn[] = Array.isArray(chatEntry?.turns) ? chatEntry.turns : [];
  if (turns.length === 0) return;
  const enabledAtIso = String(chatEntry?.agentMessageAutoContinueEnabledAt ?? '').trim();
  const enabledAtMs = enabledAtIso ? new Date(enabledAtIso).getTime() : Number.NaN;
  if (!Number.isFinite(enabledAtMs)) return;

  const llmProvider = await resolveEffectiveLlmProvider();
  const providerSettings = await resolveEffectiveProviderApiKeySettings(llmProvider.provider);
  const autoContinueSettings = await resolveEffectiveAgentMessageAutoContinueSettings();

  for (let turnIndex = 0; turnIndex < turns.length; turnIndex += 1) {
    const turn = turns[turnIndex] ?? null;
    if (!turnNeedsAgentMessageAutoContinueProcessing(turn, enabledAtMs)) continue;
    const promptId = String(turn?.id ?? '').trim();
    if (!promptId) continue;
    const sourceMessageId = buildAgentMessageAutoContinueSourceMessageId({
      droneId,
      chatName,
      turn,
    });
    if (!sourceMessageId || AGENT_MESSAGE_AUTO_CONTINUE_IN_FLIGHT.has(sourceMessageId)) continue;

    AGENT_MESSAGE_AUTO_CONTINUE_CHAT_IN_FLIGHT.add(chatLockId);
    AGENT_MESSAGE_AUTO_CONTINUE_IN_FLIGHT.add(sourceMessageId);
    await markTranscriptTurnAgentMessageAutoContinuePending({
      droneId,
      chatName,
      promptId,
    });

    void (async () => {
      try {
        const output = stripAnsiFromCliOutput(String(turn?.output ?? ''));
        const classification = await classifyAgentMessageAutoContinue(output, {
          provider: llmProvider.provider,
          apiKey: providerSettings.apiKey ?? undefined,
        });

        await markTranscriptTurnAgentMessageAutoContinueResult({
          droneId,
          chatName,
          promptId,
          classification,
        });

        let continuedAt: string | null = null;
        if (classification.bucket === 'continue') {
          const enqueued = await createOrEnqueuePromptUnified({
            droneId,
            chatName,
            prompt: autoContinueSettings.prompt,
          });
          if (enqueued.kind === 'error') throw new Error(enqueued.error);
          continuedAt = nowIso();
        }

        await markTranscriptTurnAgentMessageAutoContinueResult({
          droneId,
          chatName,
          promptId,
          classification,
          ...(continuedAt ? { continuedAt } : {}),
        });
      } catch (error: any) {
        await markTranscriptTurnAgentMessageAutoContinueFailed({
          droneId,
          chatName,
          promptId,
          error: String(error?.message ?? error ?? 'Unknown error.'),
        });
      } finally {
        AGENT_MESSAGE_AUTO_CONTINUE_IN_FLIGHT.delete(sourceMessageId);
        AGENT_MESSAGE_AUTO_CONTINUE_CHAT_IN_FLIGHT.delete(chatLockId);
      }
    })();
    return;
  }
}

function buildAgentCopilotSourceMessageId(opts: {
  droneId: string;
  chatName: string;
  turn: TranscriptTurn | null | undefined;
  turnIndex: number;
}): string {
  const droneId = normalizeDroneIdentity(opts.droneId);
  const chatName = normalizeChatName(opts.chatName);
  const turnId = String(opts.turn?.id ?? '').trim();
  if (droneId && turnId) return `${droneId}:${turnId}`;
  const at = String(opts.turn?.completedAt ?? opts.turn?.promptAt ?? opts.turn?.at ?? '').trim();
  if (!droneId || !chatName || !at) return '';
  return `${droneId}:${chatName}:${opts.turnIndex}:${at}`;
}

function readHandledAgentCopilotSourceMessageIds(chatEntry: any): string[] {
  return Array.from(
    new Set(
      (Array.isArray(chatEntry?.agentCopilotHandledSourceMessageIds) ? chatEntry.agentCopilotHandledSourceMessageIds : [])
        .map((item: any) => String(item ?? '').trim())
        .filter(Boolean),
    ),
  );
}

function hasHandledAgentCopilotSourceMessage(chatEntry: any, sourceMessageIdRaw: string): boolean {
  const sourceMessageId = String(sourceMessageIdRaw ?? '').trim();
  if (!sourceMessageId) return false;
  return readHandledAgentCopilotSourceMessageIds(chatEntry).includes(sourceMessageId);
}

async function markAgentCopilotSourceMessageHandled(opts: {
  droneId: string;
  chatName: string;
  sourceMessageId: string;
}): Promise<void> {
  const sourceMessageId = String(opts.sourceMessageId ?? '').trim();
  if (!sourceMessageId) return;
  const droneId = normalizeDroneIdentity(opts.droneId);
  const chatName = normalizeChatName(opts.chatName);
  const stored = readChatFromStore({ droneId, chatName });
  if (!stored.available || !stored.chat) return;
  const handledIds = readHandledAgentCopilotSourceMessageIds(stored.chat);
  if (handledIds.includes(sourceMessageId)) return;
  handledIds.push(sourceMessageId);
  await patchChatMetadataInStore({
    droneId,
    chatName,
    patch: {
      set: {
        agentCopilotHandledSourceMessageIds:
          handledIds.length > AGENT_COPILOT_HANDLED_CAP ? handledIds.slice(-AGENT_COPILOT_HANDLED_CAP) : handledIds,
      },
    },
  });
  await projectCanonicalChatToRegistry(droneId, chatName);
}

function buildAgentCopilotResponsePrompt(nameRaw: string, responseRaw: string): string {
  const name = String(nameRaw ?? '').trim();
  const response = String(responseRaw ?? '').trim();
  return `This is what copilot '${name}' responded with:\n${response}`;
}

function buildAgentCopilotErrorPrompt(errorRaw: string, nameRaw?: string): string {
  const error = String(errorRaw ?? '').trim() || 'Unknown error.';
  const name = String(nameRaw ?? '').trim();
  if (!name) return `Agent copilot error: ${error}`;
  return `Copilot '${name}' failed: ${error}`;
}

function buildAgentCopilotPromptId(opts: {
  sourceMessageId: string;
  stage: 'copilot' | 'source-result' | 'source-error' | 'source-parse-error';
}): string {
  const sourceMessageId = String(opts.sourceMessageId ?? '').trim();
  const digest = crypto.createHash('sha1').update(sourceMessageId).digest('hex').slice(0, 24);
  return `agent-copilot-${opts.stage}-${digest}`;
}

function getPendingPromptByIdFromRegistry(
  regAny: any,
  opts: { droneId: string; chatName: string; promptId: string },
): PendingPrompt | null {
  const pending = Array.isArray(regAny?.drones?.[opts.droneId]?.chats?.[opts.chatName]?.pendingPrompts)
    ? regAny.drones[opts.droneId].chats[opts.chatName].pendingPrompts
    : [];
  return (pending.find((item: any) => String(item?.id ?? '').trim() === opts.promptId) ?? null) as PendingPrompt | null;
}

async function ensureAgentCopilotPromptCompleted(opts: {
  droneId: string;
  chatName: string;
  promptId: string;
  prompt: string;
}): Promise<TranscriptTurn> {
  const existingTurn = getTranscriptTurnByPromptId(opts);
  if (existingTurn) return existingTurn;

  const existingPending = (await readPendingPrompts({ droneId: opts.droneId, chatName: opts.chatName }))
    .find((pending) => pending.id === opts.promptId) ?? null;
  if (!existingPending || existingPending.state === 'failed') {
    const enqueued = await createOrEnqueuePromptUnified({
      id: opts.promptId,
      droneId: opts.droneId,
      chatName: opts.chatName,
      prompt: opts.prompt,
    });
    if (enqueued.kind === 'error') throw new Error(enqueued.error);
  }

  await waitForPromptAutomationPromptCompletion({
    droneId: opts.droneId,
    chatName: opts.chatName,
    promptId: opts.promptId,
    timeoutMs: PROMPT_AUTOMATION_WAIT_FOR_PROMPT_TIMEOUT_MS,
    signal: new AbortController().signal,
  });

  const turn = getTranscriptTurnByPromptId(opts);
  if (turn) return turn;
  const pending = (await readPendingPrompts({ droneId: opts.droneId, chatName: opts.chatName }))
    .find((item) => item.id === opts.promptId) ?? null;
  if (pending?.state === 'failed') {
    throw new Error(String(pending.error ?? `prompt ${opts.promptId} failed`).trim() || `prompt ${opts.promptId} failed`);
  }
  throw new Error(`Timed out waiting for prompt ${opts.promptId} completion`);
}

async function ensureAgentCopilotSourcePromptCompleted(opts: {
  droneId: string;
  chatName: string;
  promptId: string;
  prompt: string;
}): Promise<void> {
  await ensureAgentCopilotPromptCompleted(opts);
}

async function processAgentCopilotRequest(opts: {
  sourceDroneId: string;
  sourceChatName: string;
  sourceMessageId: string;
  copilot: AgentCopilotRequest | null;
  parseError: string | null;
}): Promise<void> {
  if (opts.parseError) {
    const parseErrorPromptId = buildAgentCopilotPromptId({
      sourceMessageId: opts.sourceMessageId,
      stage: 'source-parse-error',
    });
    await ensureAgentCopilotSourcePromptCompleted({
      droneId: opts.sourceDroneId,
      chatName: opts.sourceChatName,
      promptId: parseErrorPromptId,
      prompt: buildAgentCopilotErrorPrompt(opts.parseError),
    });
    await markAgentCopilotSourceMessageHandled({
      droneId: opts.sourceDroneId,
      chatName: opts.sourceChatName,
      sourceMessageId: opts.sourceMessageId,
    });
    return;
  }

  if (!opts.copilot) return;

  const copilotChatName = parseChatNameForMutation(opts.copilot.name, 'agent copilot name');
  const copilotPromptId = buildAgentCopilotPromptId({
    sourceMessageId: opts.sourceMessageId,
    stage: 'copilot',
  });
  const sourceResultPromptId = buildAgentCopilotPromptId({
    sourceMessageId: opts.sourceMessageId,
    stage: 'source-result',
  });

  await ensureChatEntryCopiedFromChat({
    droneId: opts.sourceDroneId,
    chatName: copilotChatName,
    copyFromChatName: opts.sourceChatName,
  });
  const responseTurn = await ensureAgentCopilotPromptCompleted({
    droneId: opts.sourceDroneId,
    chatName: copilotChatName,
    promptId: copilotPromptId,
    prompt: opts.copilot.message,
  });

  const followupPrompt = responseTurn.ok
    ? buildAgentCopilotResponsePrompt(copilotChatName, stripAnsiFromCliOutput(String(responseTurn.output ?? '')))
    : buildAgentCopilotErrorPrompt(String(responseTurn.error ?? 'Copilot failed.'), copilotChatName);
  await ensureAgentCopilotSourcePromptCompleted({
    droneId: opts.sourceDroneId,
    chatName: opts.sourceChatName,
    promptId: sourceResultPromptId,
    prompt: followupPrompt,
  });

  await markAgentCopilotSourceMessageHandled({
    droneId: opts.sourceDroneId,
    chatName: opts.sourceChatName,
    sourceMessageId: opts.sourceMessageId,
  });
}

async function processPendingAgentCopilotTurns(opts: {
  droneId: string;
  chatName: string;
}): Promise<void> {
  const droneId = normalizeDroneIdentity(opts.droneId);
  const chatName = normalizeChatName(opts.chatName);
  if (!droneId || !chatName) return;

  const stored = readChatFromStore({ droneId, chatName });
  const chatEntry = stored.available ? stored.chat : null;
  if (!chatEntry) return;
  const turns: TranscriptTurn[] = Array.isArray(chatEntry?.turns) ? chatEntry.turns : [];

  for (let turnIndex = 0; turnIndex < turns.length; turnIndex += 1) {
    const turn = turns[turnIndex] ?? null;
    if (!turn?.ok || turn?.inheritedFromClone === true) continue;
    const sourceMessageId = buildAgentCopilotSourceMessageId({
      droneId,
      chatName,
      turn,
      turnIndex,
    });
    if (!sourceMessageId) continue;
    if (hasHandledAgentCopilotSourceMessage(chatEntry, sourceMessageId) || AGENT_COPILOT_IN_FLIGHT.has(sourceMessageId)) {
      continue;
    }

    const extracted = extractAgentCopilotFromAgentMessage(stripAnsiFromCliOutput(String(turn.output ?? '')));
    if (!extracted.copilot && !extracted.error) continue;

    AGENT_COPILOT_IN_FLIGHT.add(sourceMessageId);
    void processAgentCopilotRequest({
      sourceDroneId: droneId,
      sourceChatName: chatName,
      sourceMessageId,
      copilot: extracted.copilot,
      parseError: extracted.error,
    })
      .catch(async (error: any) => {
        try {
          const sourceErrorPromptId = buildAgentCopilotPromptId({
            sourceMessageId,
            stage: 'source-error',
          });
          await ensureAgentCopilotSourcePromptCompleted({
            droneId,
            chatName,
            promptId: sourceErrorPromptId,
            prompt: buildAgentCopilotErrorPrompt(
              String(error?.message ?? error ?? 'Unknown error.'),
              extracted.copilot?.name,
            ),
          });
          await markAgentCopilotSourceMessageHandled({
            droneId,
            chatName,
            sourceMessageId,
          });
        } catch {
          // Leave the source message unhandled so a later reconcile can retry.
        }
      })
      .finally(() => {
        AGENT_COPILOT_IN_FLIGHT.delete(sourceMessageId);
      });
  }
}

function promptAutomationOutputContainsStopPhrase(opts: {
  output: string;
  stopPhrase: string;
  caseSensitive: boolean;
}): boolean {
  const phrase = normalizePromptAutomationStopPhrase(opts.stopPhrase);
  if (!phrase) return false;
  const output = String(opts.output ?? '');
  if (!output) return false;
  const normalizedOutput = stripAnsiFromCliOutput(output);
  if (opts.caseSensitive) return output.includes(phrase) || normalizedOutput.includes(phrase);
  const lowerPhrase = phrase.toLowerCase();
  return output.toLowerCase().includes(lowerPhrase) || normalizedOutput.toLowerCase().includes(lowerPhrase);
}

async function preservePromptAutomationPendingHistory(opts: {
  droneId: string;
  chatName: string;
  promptId: string;
  prompt: string;
  automation: PromptAutomationMeta;
}): Promise<void> {
  const now = nowIso();
  await pushPendingPrompt({
    droneId: opts.droneId,
    chatName: opts.chatName,
    pending: {
      id: opts.promptId,
      at: now,
      prompt: opts.prompt,
      automation: normalizePromptAutomationMeta(opts.automation),
      state: 'sent',
      updatedAt: now,
    },
  }).catch(() => {});
}

async function sendPromptAutomationFinalMessage(
  job: PromptAutomationJobState,
  opts?: { ignoreAbortSignal?: boolean },
): Promise<void> {
  const finalPrompt = String(job.onFailurePrompt ?? '').trim();
  if (!finalPrompt) return;
  const ignoreAbortSignal = opts?.ignoreAbortSignal === true;
  const signal = ignoreAbortSignal
    ? null
    : job.abortController?.signal;
  if (!ignoreAbortSignal && signal?.aborted) return;
  const automation: PromptAutomationMeta = {
    kind: 'prompt-loop',
    stage: 'final-message',
    jobKey: job.executionKey,
    automationId: job.automationId,
    automationLabel: job.automationLabel,
    runsTotal: job.runsTotal,
    sleepBetweenRunsSeconds: job.sleepBetweenRunsSeconds,
    ...(job.stopPhrase ? { stopPhrase: job.stopPhrase } : {}),
    ...(job.stopPhraseCaseSensitive ? { stopPhraseCaseSensitive: true } : {}),
    ...(typeof job.finishedEarlyRunIndex === 'number' ? { stopMatchedRunIndex: job.finishedEarlyRunIndex } : {}),
    promptPreview: previewPromptAutomationPrompt(finalPrompt),
  };
  const enqueued = await createOrEnqueuePromptUnified({
    droneId: job.droneId,
    chatName: job.chatName,
    prompt: finalPrompt,
    automation,
  });
  if (enqueued.kind === 'error') throw new Error(enqueued.error);
  job.lastPromptId = enqueued.id;
  job.updatedAt = nowIso();
  await waitForPromptAutomationPromptCompletion({
    droneId: job.droneId,
    chatName: job.chatName,
    promptId: enqueued.id,
    timeoutMs: PROMPT_AUTOMATION_WAIT_FOR_PROMPT_TIMEOUT_MS,
    signal: signal ?? new AbortController().signal,
    requireTranscript: false,
  });
  await preservePromptAutomationPendingHistory({
    droneId: job.droneId,
    chatName: job.chatName,
    promptId: enqueued.id,
    prompt: finalPrompt,
    automation,
  });
  job.updatedAt = nowIso();
}

async function runPromptAutomationJob(job: PromptAutomationJobState): Promise<void> {
  let lastRunError = '';
  let hadRunFailure = false;
  try {
    for (let runIdx = 0; runIdx < job.runsTotal; runIdx++) {
      const signal = job.abortController?.signal;
      if (signal?.aborted) throw new Error('automation stopped');
      try {
        await waitForPromptAutomationChatIdle({
          droneId: job.droneId,
          chatName: job.chatName,
          timeoutMs: PROMPT_AUTOMATION_WAIT_FOR_IDLE_TIMEOUT_MS,
          signal: signal ?? new AbortController().signal,
        });

        const automation: PromptAutomationMeta = {
          kind: 'prompt-loop',
          stage: 'run',
          jobKey: job.executionKey,
          automationId: job.automationId,
          automationLabel: job.automationLabel,
          runIndex: runIdx + 1,
          runsTotal: job.runsTotal,
          sleepBetweenRunsSeconds: job.sleepBetweenRunsSeconds,
          ...(job.stopPhrase ? { stopPhrase: job.stopPhrase } : {}),
          ...(job.stopPhraseCaseSensitive ? { stopPhraseCaseSensitive: true } : {}),
          promptPreview: previewPromptAutomationPrompt(job.prompt),
        };
        const enqueued = await createOrEnqueuePromptUnified({
          droneId: job.droneId,
          chatName: job.chatName,
          prompt: job.prompt,
          automation,
        });
        if (enqueued.kind === 'error') throw new Error(enqueued.error);
        job.lastPromptId = enqueued.id;
        job.updatedAt = nowIso();
        notifyPromptAutomationChatChanged(job.droneId, job.chatName);

        await waitForPromptAutomationPromptCompletion({
          droneId: job.droneId,
          chatName: job.chatName,
          promptId: enqueued.id,
          timeoutMs: PROMPT_AUTOMATION_WAIT_FOR_PROMPT_TIMEOUT_MS,
          signal: signal ?? new AbortController().signal,
        });
        await preservePromptAutomationPendingHistory({
          droneId: job.droneId,
          chatName: job.chatName,
          promptId: enqueued.id,
          prompt: job.prompt,
          automation,
        });
        job.runsCompleted += 1;
        job.updatedAt = nowIso();
        notifyPromptAutomationChatChanged(job.droneId, job.chatName);

        if (job.stopPhrase) {
          let output = '';
          try {
            output = await readPromptAutomationTurnOutput({
              droneId: job.droneId,
              chatName: job.chatName,
              promptId: enqueued.id,
            });
          } catch {
            output = '';
          }
          if (
            promptAutomationOutputContainsStopPhrase({
              output,
              stopPhrase: job.stopPhrase,
              caseSensitive: job.stopPhraseCaseSensitive,
            })
          ) {
            job.finishedEarly = true;
            job.finishedEarlyReason = 'stop-phrase';
            job.finishedEarlyRunIndex = job.runsCompleted;
            job.runsTotal = job.runsCompleted;
            job.updatedAt = nowIso();
            notifyPromptAutomationChatChanged(job.droneId, job.chatName);
            break;
          }
        }
      } catch (e: any) {
        const msg = String(e?.message ?? e ?? '').trim();
        if (job.abortController?.signal.aborted || /automation stopped/i.test(msg)) throw e;
        hadRunFailure = true;
        lastRunError = msg || 'automation run failed';
        job.updatedAt = nowIso();
        notifyPromptAutomationChatChanged(job.droneId, job.chatName);
      }

      if (job.finishedEarly) break;
      if (runIdx < job.runsTotal - 1 && job.sleepBetweenRunsSeconds > 0) {
        const waitSignal = job.abortController?.signal ?? new AbortController().signal;
        await waitForPromptAutomationInterRunSleep({
          sleepBetweenRunsSeconds: job.sleepBetweenRunsSeconds,
          signal: waitSignal,
        });
        job.updatedAt = nowIso();
        notifyPromptAutomationChatChanged(job.droneId, job.chatName);
      }
    }

    if (job.runsCompleted > 0 && job.onFailurePrompt) {
      try {
        await sendPromptAutomationFinalMessage(job);
      } catch (followupError: any) {
        const followupMsg = String(followupError?.message ?? followupError ?? '').trim() || 'failed sending final message';
        hubLog('warn', 'prompt automation final message failed', {
          droneId: job.droneId,
          chatName: job.chatName,
          automationId: job.automationId,
          jobKey: job.executionKey,
          error: followupMsg,
        });
        if (!hadRunFailure) {
          hadRunFailure = true;
          lastRunError = `final message failed: ${followupMsg}`;
        } else {
          lastRunError = lastRunError
            ? `${lastRunError}; final message failed: ${followupMsg}`
            : `final message failed: ${followupMsg}`;
        }
      }
    }

    if (hadRunFailure) {
      job.status = 'failed';
      job.error = lastRunError || 'automation failed';
    } else {
      job.status = 'completed';
      job.error = null;
    }
    job.updatedAt = nowIso();
    notifyPromptAutomationChatChanged(job.droneId, job.chatName);
  } catch (e: any) {
    const msg = String(e?.message ?? e ?? '').trim();
    if (job.abortController?.signal.aborted || /automation stopped/i.test(msg)) {
      const stopMode = job.stopMode === 'runs-only' ? 'runs-only' : 'all';
      if (stopMode === 'runs-only') {
        let finalMessageError = '';
        if (job.runsCompleted > 0 && job.onFailurePrompt) {
          try {
            await sendPromptAutomationFinalMessage(job, { ignoreAbortSignal: true });
          } catch (followupError: any) {
            finalMessageError =
              String(followupError?.message ?? followupError ?? '').trim() || 'final message failed';
          }
        }
        job.finishedEarly = true;
        if (!job.finishedEarlyReason) job.finishedEarlyReason = 'manual-stop-runs-only';
        if (job.runsCompleted > 0) job.finishedEarlyRunIndex = job.runsCompleted;
        if (finalMessageError) {
          job.status = 'failed';
          job.error = `final message failed: ${finalMessageError}`;
        } else {
          job.status = 'stopped';
          job.error = null;
        }
        job.updatedAt = nowIso();
        notifyPromptAutomationChatChanged(job.droneId, job.chatName);
        return;
      }
      job.status = 'stopped';
      job.error = null;
      job.updatedAt = nowIso();
      notifyPromptAutomationChatChanged(job.droneId, job.chatName);
      return;
    }
    job.status = 'failed';
    job.error = msg || 'automation failed';
    job.updatedAt = nowIso();
    notifyPromptAutomationChatChanged(job.droneId, job.chatName);
  } finally {
    job.stopMode = null;
    job.abortController = null;
    job.task = null;
  }
}

type PromptAutomationJobConfig = {
  automationId: string;
  automationLabel: string;
  prompt: string;
  onFailurePrompt: string;
  runsTotal: number;
  sleepBetweenRunsSeconds: number;
  stopPhrase: string;
  stopPhraseCaseSensitive: boolean;
};

function queuePromptAutomationLaneJob(lane: PromptAutomationLaneState, cfg: PromptAutomationJobConfig): void {
  lane.queued.push({
    queueId: newPromptAutomationQueueId(lane.key),
    automationId: cfg.automationId,
    automationLabel: cfg.automationLabel,
    prompt: cfg.prompt,
    onFailurePrompt: cfg.onFailurePrompt,
    runsTotal: cfg.runsTotal,
    sleepBetweenRunsSeconds: cfg.sleepBetweenRunsSeconds,
    stopPhrase: cfg.stopPhrase,
    stopPhraseCaseSensitive: cfg.stopPhraseCaseSensitive,
    enqueuedAt: nowIso(),
  });
  lane.updatedAt = nowIso();
  notifyPromptAutomationLaneChanged(lane);
}

function finalizePromptAutomationLaneJob(lane: PromptAutomationLaneState, job: PromptAutomationJobState): void {
  if (lane.runningJob !== job) return;
  lane.runningJob = null;
  lane.lastJob = job;
  lane.updatedAt = nowIso();
  notifyPromptAutomationLaneChanged(lane);
  const next = lane.queued.shift() ?? null;
  if (next) {
    lane.updatedAt = nowIso();
    startPromptAutomationLaneJob(
      lane,
      {
        automationId: next.automationId,
        automationLabel: next.automationLabel,
        prompt: next.prompt,
        onFailurePrompt: next.onFailurePrompt,
        runsTotal: next.runsTotal,
        sleepBetweenRunsSeconds: next.sleepBetweenRunsSeconds,
        stopPhrase: next.stopPhrase,
        stopPhraseCaseSensitive: next.stopPhraseCaseSensitive,
      },
      { queuedFromId: next.queueId },
    );
    return;
  }
  // Lane is now idle; release any prompts that were intentionally queued behind automation.
  enqueuePendingPromptPump(lane.droneId, lane.chatName);
}

async function recoverStalledPromptAutomationLane(
  lane: PromptAutomationLaneState | null | undefined,
): Promise<void> {
  if (!lane || !lane.runningJob) return;
  const job = lane.runningJob;
  if (job.status !== 'running') return;
  if (job.runsTotal <= 0 || job.runsCompleted < job.runsTotal) return;

  const updatedMs = parsePromptAutomationIsoMs(job.updatedAt || job.startedAt);
  if (!updatedMs) return;
  const ageMs = Date.now() - updatedMs;
  if (ageMs < PROMPT_AUTOMATION_COMPLETION_STALL_RECOVERY_GRACE_MS) return;

  const finalPrompt = String(job.onFailurePrompt ?? '').trim();
  if (!finalPrompt) {
    job.status = 'completed';
    job.error = null;
    job.updatedAt = nowIso();
    finalizePromptAutomationLaneJob(lane, job);
    return;
  }

  const regAny: any = await loadRegistry().catch(() => null);
  if (!regAny || typeof regAny !== 'object') return;
  const finalSnapshot = readPromptAutomationFinalMessageSnapshot(regAny, job);

  if (finalSnapshot.hasFinalTranscriptTurn) {
    job.status = 'completed';
    job.error = null;
    job.updatedAt = nowIso();
    finalizePromptAutomationLaneJob(lane, job);
    return;
  }

  if (finalSnapshot.pendingFinalState === 'failed') {
    job.status = 'failed';
    job.error = 'final message failed';
    job.updatedAt = nowIso();
    finalizePromptAutomationLaneJob(lane, job);
    return;
  }

  if (!finalSnapshot.pendingFinalState) {
    job.status = 'failed';
    job.error = 'final message was not enqueued after automation runs completed';
    job.updatedAt = nowIso();
    finalizePromptAutomationLaneJob(lane, job);
    return;
  }

  if (finalSnapshot.pendingFinalState === 'queued') {
    const queuedUpdatedMs = parsePromptAutomationIsoMs(finalSnapshot.pendingFinalUpdatedAt);
    const queuedAgeMs = queuedUpdatedMs > 0 ? Date.now() - queuedUpdatedMs : 0;
    const queuedStaleAfterMs = Math.max(defaultPromptEnqueueTimeoutMs() * 2, 5 * 60_000);
    if (queuedUpdatedMs > 0 && queuedAgeMs >= queuedStaleAfterMs) {
      job.status = 'failed';
      job.error = 'final message remained queued for too long';
      job.updatedAt = nowIso();
      finalizePromptAutomationLaneJob(lane, job);
    }
    return;
  }

  const staleFinalState = stalePendingPromptState({
    state: finalSnapshot.pendingFinalState,
    updatedAt: finalSnapshot.pendingFinalUpdatedAt,
    at: finalSnapshot.pendingFinalUpdatedAt,
    enqueueTimeoutMs: defaultPromptEnqueueTimeoutMs(),
  });
  if (staleFinalState === 'sending' || staleFinalState === 'sent') {
    job.status = 'failed';
    job.error = 'final message stalled before transcript reconciliation';
    job.updatedAt = nowIso();
    finalizePromptAutomationLaneJob(lane, job);
  }
}

function startPromptAutomationLaneJob(
  lane: PromptAutomationLaneState,
  cfg: PromptAutomationJobConfig,
  opts?: { queuedFromId?: string | null },
): PromptAutomationJobState {
  const job: PromptAutomationJobState = {
    key: lane.key,
    executionKey: newPromptAutomationExecutionKey(lane.key),
    queuedFromId: opts?.queuedFromId ?? null,
    droneId: lane.droneId,
    chatName: lane.chatName,
    automationId: cfg.automationId,
    automationLabel: cfg.automationLabel,
    prompt: cfg.prompt,
    onFailurePrompt: cfg.onFailurePrompt,
    runsTotal: cfg.runsTotal,
    sleepBetweenRunsSeconds: cfg.sleepBetweenRunsSeconds,
    stopPhrase: cfg.stopPhrase,
    stopPhraseCaseSensitive: cfg.stopPhraseCaseSensitive,
    runsCompleted: 0,
    finishedEarly: false,
    finishedEarlyReason: null,
    finishedEarlyRunIndex: null,
    status: 'running',
    startedAt: nowIso(),
    updatedAt: nowIso(),
    lastPromptId: null,
    error: null,
    stopMode: null,
    abortController: new AbortController(),
    task: null,
  };
  lane.runningJob = job;
  lane.updatedAt = nowIso();
  notifyPromptAutomationLaneChanged(lane);
  job.task = runPromptAutomationJob(job).finally(() => {
    finalizePromptAutomationLaneJob(lane, job);
  });
  void job.task;
  return job;
}

async function startPromptAutomationJob(opts: {
  droneId: string;
  chatName: string;
  automationId: string;
  automationLabel: string;
  prompt: string;
  onFailurePrompt?: string;
  runs: number;
  sleepBetweenRunsSeconds?: number;
  stopPhrase?: string;
  stopPhraseCaseSensitive?: boolean;
}): Promise<PromptAutomationLaneState> {
  const droneId = normalizeDroneIdentity(opts.droneId);
  const chatName = normalizeChatName(opts.chatName);
  const automationId = String(opts.automationId ?? '').trim();
  const automationLabel = String(opts.automationLabel ?? '').trim() || automationId || 'Automation';
  const prompt = String(opts.prompt ?? '').trim();
  const onFailurePrompt = normalizePromptAutomationOnFailurePrompt(opts.onFailurePrompt);
  const runs = normalizePromptAutomationRuns(opts.runs);
  const sleepBetweenRunsSeconds = normalizePromptAutomationSleepBetweenRunsSeconds(opts.sleepBetweenRunsSeconds);
  const stopPhrase = normalizePromptAutomationStopPhrase(opts.stopPhrase);
  const stopPhraseCaseSensitive = normalizePromptAutomationStopPhraseCaseSensitive(opts.stopPhraseCaseSensitive);
  if (!prompt) throw new Error('missing prompt');
  if (!automationId) throw new Error('missing automation id');

  await ensureChatEntry({ droneId, chatName });
  const { d, chat } = await getChatEntry({ droneId, chatName });
  const agent = inferChatAgent(chat, d);
  if (!(agent.kind === 'builtin')) {
    throw new Error('automation requires a builtin transcript agent');
  }

  const lane = ensurePromptAutomationLane(droneId, chatName);
  const cfg: PromptAutomationJobConfig = {
    automationId,
    automationLabel,
    prompt,
    onFailurePrompt,
    runsTotal: runs,
    sleepBetweenRunsSeconds,
    stopPhrase,
    stopPhraseCaseSensitive,
  };
  if (lane.runningJob) {
    queuePromptAutomationLaneJob(lane, cfg);
    return lane;
  }
  startPromptAutomationLaneJob(lane, cfg);
  return lane;
}

function stopPromptAutomationJob(opts: {
  droneId: string;
  chatName: string;
  stopMode?: PromptAutomationStopMode;
  clearQueued?: boolean;
}): PromptAutomationLaneState | null {
  const lane = getPromptAutomationLane(opts.droneId, opts.chatName);
  if (!lane) return null;
  const stopMode: PromptAutomationStopMode = opts.stopMode === 'runs-only' ? 'runs-only' : 'all';
  const clearQueued = opts.clearQueued !== false;
  if (clearQueued && lane.queued.length > 0) {
    lane.queued = [];
  }
  const running = lane.runningJob;
  if (running && running.status === 'running') {
    running.stopMode = stopMode;
    running.abortController?.abort();
    running.status = 'stopped';
    running.error = null;
    running.updatedAt = nowIso();
  }
  lane.updatedAt = nowIso();
  if (!promptAutomationLaneBusy(lane, { includeQueued: true })) {
    enqueuePendingPromptPump(lane.droneId, lane.chatName);
  }
  notifyPromptAutomationLaneChanged(lane);
  return lane;
}

type CancelQueuedPromptAutomationStatus = 'cancelled' | 'already-submitted' | 'not-found';

function cancelQueuedPromptAutomationRun(opts: {
  droneId: string;
  chatName: string;
  queueId: string;
}): {
  lane: PromptAutomationLaneState | null;
  status: CancelQueuedPromptAutomationStatus;
} {
  const lane = getPromptAutomationLane(opts.droneId, opts.chatName);
  const queueId = String(opts.queueId ?? '').trim();
  if (!lane || !queueId) return { lane, status: 'not-found' };

  const idx = lane.queued.findIndex((q) => String(q?.queueId ?? '').trim() === queueId);
  if (idx >= 0) {
    lane.queued.splice(idx, 1);
    lane.updatedAt = nowIso();
    if (!promptAutomationLaneBusy(lane, { includeQueued: true })) {
      enqueuePendingPromptPump(lane.droneId, lane.chatName);
    }
    notifyPromptAutomationLaneChanged(lane);
    return { lane, status: 'cancelled' };
  }

  const runningFromQueue = String(lane.runningJob?.queuedFromId ?? '').trim();
  if (runningFromQueue && runningFromQueue === queueId) {
    return { lane, status: 'already-submitted' };
  }
  const lastFromQueue = String(lane.lastJob?.queuedFromId ?? '').trim();
  if (lastFromQueue && lastFromQueue === queueId) {
    return { lane, status: 'already-submitted' };
  }
  return { lane, status: 'not-found' };
}

// Hub-side pump for `pendingPrompts` entries that are persisted but not yet enqueued
// into the drone daemon (state: 'queued'). This is used to preserve session continuity
// for agents where the continuation/session id is only known after the first turn.
const PENDING_PROMPT_PUMP_TASKS = new Map<string, Promise<void>>();
const PENDING_PROMPT_PUMP_QUEUE: Array<{ droneId: string; chatName: string }> = [];
const PENDING_PROMPT_PUMP_QUEUED = new Set<string>();
const PENDING_PROMPT_PUMP_RETRY = new Set<string>();
const PENDING_PROMPT_PUMP_RETRY_TIMERS = new Map<string, ReturnType<typeof setTimeout>>();
let PENDING_PROMPT_PUMP_ACTIVE = 0;
let PENDING_PROMPT_PUMP_PUMPING = false;

function pendingPromptPumpConcurrencyLimit(): number {
  const raw = String(process.env.DRONE_HUB_PENDING_PROMPT_PUMP_CONCURRENCY ?? '').trim();
  const n = raw ? Number(raw) : NaN;
  if (Number.isFinite(n) && n >= 1) return Math.max(1, Math.min(16, Math.floor(n)));
  return 6;
}

function interruptedPromptDeliveryError(raw: unknown): string {
  const detail = String(raw ?? '').trim().replace(/\s+/g, ' ').slice(0, 240);
  return detail
    ? `Prompt delivery was interrupted; retrying when the drone daemon is available. Last error: ${detail}`
    : 'Prompt delivery was interrupted; retrying when the drone daemon is available.';
}

async function pumpQueuedPendingPromptsForChat(opts: { droneId: string; chatName: string }): Promise<void> {
  const droneId = normalizeDroneIdentity(opts.droneId);
  const chatName = String(opts.chatName ?? '').trim() || 'default';
  if (!droneId) return;

  // Avoid unbounded loops if state keeps changing due to concurrent requests.
  for (let attempts = 0; attempts < 50; attempts++) {
    const { d, chat } = await getChatEntry({ droneId, chatName });
    if (isDraftChatEntry(chat)) return;
    const agent = inferChatAgent(chat, d);
    if (!agent || agent.kind !== 'builtin') return;

    const entry: any = chat;
    // Prompt rows are canonical in SQLite; the registry-backed chat projection
    // is compatibility metadata and can lag queue transitions.
    const pendingList: any[] = await readPendingPrompts({ droneId, chatName });
    if (pendingList.length === 0) return;

    const turns: any[] = Array.isArray(entry?.turns) ? entry.turns : [];
    const transcriptDoneIds = new Set(turns.map((t: any) => String(t?.id ?? '').trim()).filter(Boolean));

    const idx = pendingList.findIndex((p: any) => String(p?.state ?? '') === 'queued' && String(p?.id ?? '').trim());
    if (idx === -1) return;

    const p = pendingList[idx] ?? {};
    const id = String(p?.id ?? '').trim();
    const prompt = String(p?.prompt ?? '');
    const cwd = typeof p?.cwd === 'string' ? String(p.cwd) : null;
    const blockedByAutomation = Boolean((p as any)?.blockedByAutomation);
    if (!id || !prompt.trim()) {
      // Mark invalid entries as failed so they don't block forever.
      await updatePendingPrompt({ droneId, chatName, id, patch: { state: 'failed', error: 'invalid queued prompt' } }).catch(() => {});
      continue;
    }

    if (blockedByAutomation) {
      const lane = getPromptAutomationLane(droneId, chatName);
      if (promptAutomationLaneBusy(lane, { includeQueued: true })) {
        // Held intentionally behind automation lane completion.
        return;
      }
    }

    const sessionKnown = hasKnownBuiltinTranscriptSession(entry, agent.id);
    const prior = pendingList
      .slice(0, idx)
      .map((x: any) => ({ id: String(x?.id ?? '').trim(), state: String(x?.state ?? '') }))
      .filter((x: any) => x.id);
    const defer = shouldDeferQueuedTranscriptPrompt({
      agentId: agent.id,
      sessionKnown,
      priorPendingPrompts: prior,
      transcriptDoneIds,
    });
    if (defer) return;

    // Transition queued -> sending before we attempt any daemon work.
    // This claim is atomic to prevent a race where a user cancels a queued row.
    const claimed = await claimQueuedPendingPromptForSending({ droneId, chatName, id });
    if (!claimed) {
      continue;
    }

    try {
      const enqueueTimeoutMs = defaultPromptEnqueueTimeoutMs();
      const r: any = await withTimeout(
        sendPromptToChat({
          id,
          droneId,
          chatName,
          prompt,
          attachmentRefs: normalizeChatImageAttachmentRefs(p?.attachments),
          cwd,
          waitForDaemonMs: undefined,
          skipManagedRepoSync: String((p as any)?.automation?.kind ?? '').trim() === 'prompt-loop',
        }),
        enqueueTimeoutMs,
        `queued prompt enqueue failed for ${droneId}/${chatName}`,
      );
      if (r?.turnOk === false) {
        await updatePendingPrompt({
          droneId,
          chatName,
          id,
          patch: { state: 'failed', error: String(r?.error ?? 'failed') },
        });
      } else {
        await updatePendingPrompt({ droneId, chatName, id, patch: { state: 'sent' } });
        // Best-effort: reconcile soon after enqueue to keep UI fresh.
        enqueueReconcile(droneId, chatName);
      }
    } catch (e: any) {
      const errorText = e?.message ?? String(e);
      const diagnostics =
        looksLikeTransientPromptEnqueueError(errorText) || looksLikeContainerPausedError(errorText)
          ? await collectDroneRuntimeDiagnostics({ droneId, droneEntry: d }).catch((error) => ({ diagnosticError: compactDiagnosticError(error) }))
          : null;
      hubLog('warn', 'queued pending prompt enqueue failed', {
        droneId,
        chatName,
        promptId: id,
        error: String(errorText ?? 'unknown error'),
        ...(diagnostics ? { diagnostics } : {}),
      });
      if (looksLikeTransientPromptEnqueueError(errorText)) {
        const retry = await retryPendingPrompt({
          droneId,
          chatName,
          id,
          error: interruptedPromptDeliveryError(errorText),
        });
        if (retry.disposition === 'retry') {
          const nextMs = retry.nextAttemptAt ? Date.parse(retry.nextAttemptAt) : NaN;
          schedulePendingPromptPumpRetry(
            droneId,
            chatName,
            Number.isFinite(nextMs) ? Math.max(1_000, nextMs - Date.now()) : undefined,
          );
        }
        return;
      }
      await updatePendingPrompt({
        droneId,
        chatName,
        id,
        patch: { state: 'failed', error: errorText },
      });
    }
  }
}

function pumpPendingPromptQueue() {
  if (PENDING_PROMPT_PUMP_PUMPING) return;
  PENDING_PROMPT_PUMP_PUMPING = true;
  try {
    const limit = pendingPromptPumpConcurrencyLimit();
    while (PENDING_PROMPT_PUMP_ACTIVE < limit && PENDING_PROMPT_PUMP_QUEUE.length > 0) {
      const next = PENDING_PROMPT_PUMP_QUEUE.shift();
      if (!next) break;
      const droneId = normalizeDroneIdentity(next.droneId);
      const chatName = String(next.chatName ?? '').trim() || 'default';
      if (!droneId) continue;
      const key = `${droneId}:${chatName}`;
      PENDING_PROMPT_PUMP_QUEUED.delete(key);
      if (PENDING_PROMPT_PUMP_TASKS.has(key)) continue;
      PENDING_PROMPT_PUMP_ACTIVE += 1;
      const p = pumpQueuedPendingPromptsForChat({ droneId, chatName })
        .catch(() => {
          // ignore (best-effort)
        })
        .finally(() => {
          PENDING_PROMPT_PUMP_ACTIVE -= 1;
          PENDING_PROMPT_PUMP_TASKS.delete(key);
          if (PENDING_PROMPT_PUMP_RETRY.delete(key)) {
            enqueuePendingPromptPump(droneId, chatName);
          }
          pumpPendingPromptQueue();
        });
      PENDING_PROMPT_PUMP_TASKS.set(key, p);
      void p;
    }
  } finally {
    PENDING_PROMPT_PUMP_PUMPING = false;
  }
}

export async function resetPromptAutomationStateForTests(): Promise<void> {
  const automationTasks: Promise<void>[] = [];
  for (const lane of PROMPT_AUTOMATION_LANES.values()) {
    lane.queued = [];
    const running = lane.runningJob;
    if (!running) continue;
    running.stopMode = 'all';
    running.abortController?.abort();
    if (running.task) automationTasks.push(running.task.catch(() => {}));
  }
  await Promise.allSettled(automationTasks);
  PROMPT_AUTOMATION_LANES.clear();
  PENDING_PROMPT_PUMP_QUEUE.length = 0;
  PENDING_PROMPT_PUMP_QUEUED.clear();
  PENDING_PROMPT_PUMP_RETRY.clear();
  for (const timer of PENDING_PROMPT_PUMP_RETRY_TIMERS.values()) clearTimeout(timer);
  PENDING_PROMPT_PUMP_RETRY_TIMERS.clear();
  await Promise.allSettled(Array.from(PENDING_PROMPT_PUMP_TASKS.values()).map((task) => task.catch(() => {})));
  PENDING_PROMPT_PUMP_TASKS.clear();
  PENDING_PROMPT_PUMP_ACTIVE = 0;
  PENDING_PROMPT_PUMP_PUMPING = false;
  resetTranscriptStoreForTests();
}

function clearPendingPromptPumpRetryByKey(key: string): void {
  const timer = PENDING_PROMPT_PUMP_RETRY_TIMERS.get(key);
  if (!timer) return;
  clearTimeout(timer);
  PENDING_PROMPT_PUMP_RETRY_TIMERS.delete(key);
}

function enqueuePendingPromptPump(droneIdRaw: string, chatName: string) {
  const dn = normalizeDroneIdentity(droneIdRaw);
  const cn = String(chatName ?? '').trim() || 'default';
  if (!dn) return;
  const key = `${dn}:${cn}`;
  clearPendingPromptPumpRetryByKey(key);
  if (PENDING_PROMPT_PUMP_TASKS.has(key)) {
    // Preserve edge-trigger requests that arrive while a pump task is active.
    // Without this, an unblock signal can be lost during the task's teardown window.
    PENDING_PROMPT_PUMP_RETRY.add(key);
    return;
  }
  if (PENDING_PROMPT_PUMP_QUEUED.has(key)) return;
  PENDING_PROMPT_PUMP_QUEUED.add(key);
  PENDING_PROMPT_PUMP_QUEUE.push({ droneId: dn, chatName: cn });
  pumpPendingPromptQueue();
}

function schedulePendingPromptPumpRetry(droneIdRaw: string, chatNameRaw: string, delayMs: number = defaultPendingPromptEnqueueRetryDelayMs()) {
  const droneId = normalizeDroneIdentity(droneIdRaw);
  if (!droneId) return;
  const chatName = normalizeChatName(chatNameRaw);
  const key = `${droneId}:${chatName}`;
  if (PENDING_PROMPT_PUMP_RETRY_TIMERS.has(key)) return;
  const ms = Number.isFinite(delayMs) ? Math.max(1_000, Math.floor(delayMs)) : defaultPendingPromptEnqueueRetryDelayMs();
  const timer = setTimeout(() => {
    PENDING_PROMPT_PUMP_RETRY_TIMERS.delete(key);
    enqueuePendingPromptPump(droneId, chatName);
  }, ms);
  (timer as any).unref?.();
  PENDING_PROMPT_PUMP_RETRY_TIMERS.set(key, timer);
}

function droneChatMapKey(droneIdRaw: string, chatNameRaw: string): string {
  const droneId = normalizeDroneIdentity(droneIdRaw);
  if (!droneId) return '';
  const chatName = normalizeChatName(chatNameRaw);
  return `${droneId}:${chatName}`;
}

function clearInMemoryChatStateForDelete(opts: { droneId: string; chatName: string }) {
  const key = droneChatMapKey(opts.droneId, opts.chatName);
  if (!key) return;

  const hadAutomationLane = PROMPT_AUTOMATION_LANES.delete(key);
  if (hadAutomationLane) notifyPromptAutomationChatChanged(opts.droneId, opts.chatName);

  clearScheduledReconcileRetryByKey(key);
  RECONCILE_QUEUED.delete(key);
  for (let i = RECONCILE_QUEUE.length - 1; i >= 0; i -= 1) {
    const item = RECONCILE_QUEUE[i];
    if (droneChatMapKey(String(item?.droneName ?? ''), String(item?.chatName ?? '')) !== key) continue;
    RECONCILE_QUEUE.splice(i, 1);
  }

  PENDING_PROMPT_PUMP_QUEUED.delete(key);
  PENDING_PROMPT_PUMP_RETRY.delete(key);
  clearPendingPromptPumpRetryByKey(key);
  for (let i = PENDING_PROMPT_PUMP_QUEUE.length - 1; i >= 0; i -= 1) {
    const item = PENDING_PROMPT_PUMP_QUEUE[i];
    if (droneChatMapKey(String(item?.droneId ?? ''), String(item?.chatName ?? '')) !== key) continue;
    PENDING_PROMPT_PUMP_QUEUE.splice(i, 1);
  }
}

function migrateInMemoryChatStateForRename(opts: { droneId: string; fromChatName: string; toChatName: string }) {
  const fromKey = droneChatMapKey(opts.droneId, opts.fromChatName);
  const toKey = droneChatMapKey(opts.droneId, opts.toChatName);
  if (!fromKey || !toKey || fromKey === toKey) return;

  const lane = PROMPT_AUTOMATION_LANES.get(fromKey);
  if (lane) {
    PROMPT_AUTOMATION_LANES.delete(fromKey);
    notifyPromptAutomationChatChanged(opts.droneId, opts.fromChatName);
    lane.key = toKey;
    lane.chatName = normalizeChatName(opts.toChatName);
    if (lane.runningJob) {
      lane.runningJob.key = toKey;
      lane.runningJob.chatName = lane.chatName;
    }
    if (lane.lastJob) {
      lane.lastJob.key = toKey;
      lane.lastJob.chatName = lane.chatName;
    }
    PROMPT_AUTOMATION_LANES.set(toKey, lane);
    notifyPromptAutomationLaneChanged(lane);
  }

  clearScheduledReconcileRetryByKey(fromKey);
  if (RECONCILE_QUEUED.delete(fromKey)) RECONCILE_QUEUED.add(toKey);
  for (const item of RECONCILE_QUEUE) {
    if (droneChatMapKey(String(item?.droneName ?? ''), String(item?.chatName ?? '')) !== fromKey) continue;
    item.chatName = normalizeChatName(opts.toChatName);
  }

  if (PENDING_PROMPT_PUMP_QUEUED.delete(fromKey)) PENDING_PROMPT_PUMP_QUEUED.add(toKey);
  const retryTimer = PENDING_PROMPT_PUMP_RETRY_TIMERS.get(fromKey);
  if (retryTimer) {
    clearPendingPromptPumpRetryByKey(fromKey);
    schedulePendingPromptPumpRetry(opts.droneId, opts.toChatName);
  }
  for (const item of PENDING_PROMPT_PUMP_QUEUE) {
    if (droneChatMapKey(String(item?.droneId ?? ''), String(item?.chatName ?? '')) !== fromKey) continue;
    item.chatName = normalizeChatName(opts.toChatName);
  }
}

function chatHasActivePendingPromptsForSummary(entry: any): boolean {
  const pending = Array.isArray(entry?.pendingPrompts) ? entry.pendingPrompts : [];
  if (pending.length === 0) return false;
  const turns = Array.isArray(entry?.turns) ? entry.turns : [];
  const doneIds = new Set(turns.map((t: any) => String(t?.id ?? '').trim()).filter(Boolean));
  for (const p of pending) {
    const st = String(p?.state ?? '').trim();
    if (st === 'failed') continue;
    const id = String(p?.id ?? '').trim();
    if (!id || !doneIds.has(id)) return true;
  }
  return false;
}

type BusyChatDebugEntry = {
  chatName: string;
  reasons: string[];
  pendingPrompts: Array<{ id: string; state: string; hasTurn: boolean }>;
};

const droneBusyDebugLastById = new Map<string, string>();

function droneBusyDebugEnabled(): boolean {
  return String(process.env.DRONE_HUB_BUSY_DEBUG ?? '').trim() !== '0';
}

function busyChatDebugForEntry(droneId: string, chatName: string, entry: any): BusyChatDebugEntry {
  const reasons: string[] = [];
  const pending = Array.isArray(entry?.pendingPrompts) ? entry.pendingPrompts : [];
  const turns = Array.isArray(entry?.turns) ? entry.turns : [];
  const doneIds = new Set(turns.map((t: any) => String(t?.id ?? '').trim()).filter(Boolean));
  const pendingPrompts = pending
    .map((p: any) => {
      const id = String(p?.id ?? '').trim();
      return {
        id,
        state: String(p?.state ?? '').trim(),
        hasTurn: Boolean(id && doneIds.has(id)),
      };
    })
    .filter((p: { id: string }) => p.id);
  if (chatHasActivePendingPromptsForSummary(entry)) reasons.push('active-pending-prompt');
  if (promptAutomationLaneBusy(getPromptAutomationLane(droneId, chatName), { includeQueued: true })) {
    reasons.push('prompt-automation');
  }
  if (chatHasActiveDockerSnapshot(entry)) reasons.push('docker-snapshot');
  return { chatName, reasons, pendingPrompts };
}

function logDroneBusyDebugChange(d: any, droneId: string, diagnostics: BusyChatDebugEntry[]): void {
  if (!droneBusyDebugEnabled()) return;
  const busyChats = diagnostics.filter((item) => item.reasons.length > 0);
  const signature = JSON.stringify(busyChats);
  if (droneBusyDebugLastById.get(droneId) === signature) return;
  droneBusyDebugLastById.set(droneId, signature);
  console.log('[DroneHub][busy-debug] summary busy changed', {
    droneId,
    name: String(d?.name ?? droneId).trim() || droneId,
    busy: busyChats.length > 0,
    busyChats,
  });
}

function busyChatNamesForDrone(d: any, droneIdRaw: string): string[] {
  const droneId = normalizeDroneIdentity(droneIdRaw);
  if (!droneId) return [];
  const chats = d?.chats && typeof d.chats === 'object' ? Object.entries(d.chats) : [];
  const out: string[] = [];
  const diagnostics: BusyChatDebugEntry[] = [];
  for (const [chatNameRaw, entry] of chats as Array<[string, any]>) {
    const chatName = normalizeChatName(chatNameRaw);
    if (!chatName || out.includes(chatName)) continue;
    const debug = busyChatDebugForEntry(droneId, chatName, entry);
    diagnostics.push(debug);
    if (debug.reasons.length > 0) out.push(chatName);
  }
  logDroneBusyDebugChange(d, droneId, diagnostics);
  return out;
}

function chatHasReconcilablePendingPrompts(entry: any): boolean {
  const pending = Array.isArray(entry?.pendingPrompts) ? entry.pendingPrompts : [];
  if (pending.length === 0) return false;
  const turns = Array.isArray(entry?.turns) ? entry.turns : [];
  const doneIds = new Set(turns.map((t: any) => String(t?.id ?? '').trim()).filter(Boolean));
  for (const p of pending) {
    const st = String(p?.state ?? '');
    if (st === 'failed') {
      if (
        !shouldRetryFailedPendingPrompt({
          error: p?.error,
          updatedAt: typeof p?.updatedAt === 'string' ? p.updatedAt : null,
          at: typeof p?.at === 'string' ? p.at : null,
        })
      ) {
        continue;
      }
    }
    // `queued` entries haven't been enqueued into the daemon yet, so there's nothing
    // to reconcile from daemon → transcript for them.
    if (st === 'queued') continue;
    const id = String(p?.id ?? '').trim();
    if (!id) continue;
    if (!doneIds.has(id)) return true;
  }
  return false;
}

function normalizePendingBlipClones(raw: any): { status: 'running'; count: number; tasks: string[] } | undefined {
  if (!raw || typeof raw !== 'object') return undefined;
  if (String(raw.status ?? '').trim() !== 'running') return undefined;
  const tasks = Array.isArray(raw.tasks) ? raw.tasks.map((task: any) => String(task ?? '').trim()).filter(Boolean).slice(0, 8) : [];
  if (tasks.length === 0) return undefined;
  const countRaw = Number(raw.count);
  const count = Number.isFinite(countRaw) && countRaw > 0 ? Math.floor(countRaw) : tasks.length;
  return { status: 'running', count: Math.max(1, count), tasks };
}

function samePendingBlipClones(leftRaw: any, rightRaw: any): boolean {
  const left = normalizePendingBlipClones(leftRaw);
  const right = normalizePendingBlipClones(rightRaw);
  if (!left && !right) return true;
  if (!left || !right) return false;
  if (left.count !== right.count || left.tasks.length !== right.tasks.length) return false;
  return left.tasks.every((task, index) => task === right.tasks[index]);
}

async function reconcileChatFromDaemon(opts: { droneId: string; chatName: string }): Promise<void> {
  const droneId = normalizeDroneIdentity(opts.droneId);
  const chatName = normalizeChatName(opts.chatName);
  let d: any = null;
  let entry: any = null;
  if (!(globalThis as any).Bun) {
    const resolved = droneId ? await resolveCanonicalDroneOrPendingForReadRef(droneId) : null;
    if (resolved?.kind === 'real') d = resolved.drone;
    const stored = droneId ? readChatFromStore({ droneId, chatName }) : null;
    entry = stored?.available ? stored.chat : null;
  } else {
    const regAny: any = await loadRegistry();
    d = droneId ? regAny?.drones?.[droneId] : null;
    const registryEntry = d?.chats?.[chatName];
    if (registryEntry) {
      await importChatFromRegistry({ droneId, chatName, chatEntry: registryEntry });
      const projectedEntry = readChatFromStore({ droneId, chatName });
      entry = projectedEntry.available && projectedEntry.chat ? projectedEntry.chat : registryEntry;
    }
  }
  if (!d) return;
  const token = typeof d.token === 'string' ? d.token : '';
  const containerName = String(d?.containerName ?? d?.name ?? droneId).trim() || droneId;
  const runtime = droneRuntime(d);
  const hostPort =
    typeof d.hostPort === 'number' && Number.isFinite(d.hostPort)
      ? d.hostPort
      : await resolveHostPort(containerName, d.containerPort);
  if (!hostPort || !token) return;

  if (!entry) return;
  const agent = inferChatAgent(entry, d);
  if (!agent || agent.kind !== 'builtin') return;

  const pendingList: any[] = Array.isArray(entry?.pendingPrompts) ? entry.pendingPrompts : [];
  if (pendingList.length === 0) {
    clearScheduledReconcileRetryByKey(droneChatMapKey(droneId, chatName));
    void processPendingAgentCopilotTurns({ droneId, chatName }).catch((error: any) => {
      hubLog('warn', 'agent copilot scan failed after reconcile', {
        droneId,
        chatName,
        error: String(error?.message ?? error ?? 'unknown error'),
      });
    });
    void processPendingAgentMessageAutoContinueTurns({ droneId, chatName }).catch((error: any) => {
      hubLog('warn', 'agent message auto-continue scan failed after reconcile', {
        droneId,
        chatName,
        error: String(error?.message ?? error ?? 'unknown error'),
      });
    });
    return;
  }

  const turns: any[] = Array.isArray(entry?.turns) ? entry.turns : [];
  const pendingBefore = new Map(
    pendingList.map((pending: any) => [String(pending?.id ?? '').trim(), JSON.stringify(pending)] as const).filter(([id]) => Boolean(id)),
  );
  const initialTurnIds = new Set(turns.map((turn: any) => String(turn?.id ?? '').trim()).filter(Boolean));
  const metadataBefore = Object.fromEntries(
    ['codexThreadId', 'claudeSessionId', 'openCodeSessionId', 'piSessionId', 'blipSessionId']
      .map((field) => [field, String((entry as any)?.[field] ?? '').trim()]),
  ) as Record<string, string>;
  const transcriptIds = new Set(turns.map((t: any) => String(t?.id ?? '').trim()).filter(Boolean));

  const client = makeClient(hostPort, token);
  let changed = false;
  const completedTurnIdsForSnapshot: string[] = [];
  for (let i = 0; i < pendingList.length; i++) {
    const p = pendingList[i] ?? {};
    const id = String(p?.id ?? '').trim();
    const state = String(p?.state ?? '');
    const promptAttachments = normalizeChatImageAttachmentRefs((p as any)?.attachments);
    const promptAutomation = normalizePromptAutomationMeta((p as any)?.automation);
    const pendingModel = normalizeChatModel((p as any)?.model) ?? normalizeChatModel((entry as any)?.model);
    if (!id) continue;
    if (state === 'queued') continue;

    // If already in transcript, nothing to do.
    if (transcriptIds.has(id)) {
      if (state !== 'sent') {
        pendingList[i] = { ...p, state: 'sent', observability: undefined, updatedAt: nowIso() };
        changed = true;
      }
      continue;
    }
    if (state === 'failed') {
      if (
        !shouldRetryFailedPendingPrompt({
          error: p?.error,
          updatedAt: typeof p?.updatedAt === 'string' ? p.updatedAt : null,
          at: typeof p?.at === 'string' ? p.at : null,
        })
      ) {
        continue;
      }
    }

    let jobResp: any = null;
    try {
      // eslint-disable-next-line no-await-in-loop
      jobResp = await dronePromptGet(client, id);
    } catch (error: any) {
      // If daemon job lookups fail after acceptance, keep the prompt active and
      // surface observability loss separately from agent failure.
      const staleState = stalePendingPromptState({
        state,
        updatedAt: typeof p?.updatedAt === 'string' ? p.updatedAt : null,
        at: typeof p?.at === 'string' ? p.at : null,
        enqueueTimeoutMs: defaultPromptEnqueueTimeoutMs(),
      });
      if (staleState === 'sending' || staleState === 'sent') {
        const diagnostics = await collectDroneRuntimeDiagnostics({ droneId, droneEntry: d }).catch((error) => ({
          diagnosticError: compactDiagnosticError(error),
        }));
        hubLog('warn', 'pending prompt daemon status unavailable after stale threshold', {
          droneId,
          chatName,
          promptId: id,
          pendingState: state,
          staleState,
          diagnostics,
        });
        if (staleState === 'sending') {
          pendingList[i] = {
            ...p,
            state: 'queued',
            error: interruptedPromptDeliveryError('daemon status unavailable while prompt was being delivered'),
            observability: undefined,
            updatedAt: nowIso(),
          };
          schedulePendingPromptPumpRetry(droneId, chatName);
        } else {
          const checkedAt = nowIso();
          const errorText = String(error?.message ?? error ?? '').trim();
          pendingList[i] = {
            ...p,
            state: 'sent',
            observability: {
              state: 'status-unavailable',
              message: 'Prompt status is temporarily unavailable. The agent may still be running.',
              lastCheckedAt: checkedAt,
              ...(errorText ? { lastError: errorText.slice(0, 240) } : {}),
            },
            updatedAt: checkedAt,
          };
          scheduleReconcileRetry(droneId, chatName, 10_000);
        }
        changed = true;
      }
      continue;
    }
    let job = jobResp?.job ?? null;
    let jobState = String(job?.state ?? '').trim();
    let jobKind = normalizeBuiltinAgentId(job?.kind) ?? agent.id;
    if (jobState === 'queued' || jobState === 'running') {
      const parsedBlip = jobKind === 'blip' && jobState === 'running' ? parseBlipJobTranscript(job) : null;
      if (parsedBlip?.sessionId && String(parsedBlip.sessionId).trim() && String(entry?.blipSessionId ?? '').trim() !== parsedBlip.sessionId) {
        entry.blipSessionId = parsedBlip.sessionId;
        changed = true;
      }
      const nextBlipClones = parsedBlip?.cloneActivity;
      const blipClonesChanged = jobKind === 'blip' && !samePendingBlipClones((p as any).blipClones, nextBlipClones);
      const observabilityChanged = Boolean((p as any).observability);
      if (state !== 'sent' || blipClonesChanged || observabilityChanged) {
        pendingList[i] = { ...p, state: 'sent', observability: undefined, blipClones: nextBlipClones, updatedAt: nowIso() };
        changed = true;
        continue;
      }
      const staleState = stalePendingPromptState({
        state,
        updatedAt: typeof p?.updatedAt === 'string' ? p.updatedAt : null,
        at: typeof p?.at === 'string' ? p.at : null,
        enqueueTimeoutMs: defaultPromptEnqueueTimeoutMs(),
      });
      if (staleState !== 'sent') continue;

      // A running prompt can legitimately exceed the enqueue timeout. Do not kill
      // active agent work here; cancellation has to preserve an explicit cause.
      if (jobState === 'running') continue;

      // Auto-recover stale queued prompt jobs by closing any leftover prompt tmux session.
      const recovered = await recoverStalePromptJobSession({ droneId, droneEntry: d, promptId: id });
      if (recovered.jobState && recovered.job) {
        job = recovered.job;
        jobState = recovered.jobState;
        jobKind = normalizeBuiltinAgentId(job?.kind) ?? agent.id;
      } else {
        pendingList[i] = {
          ...p,
          state: 'failed',
          error: `auto-finalized stale pending prompt; daemon job remained ${jobState || 'non-terminal'} until session recovery`,
          observability: undefined,
          updatedAt: nowIso(),
        };
        changed = true;
        continue;
      }
    }

    if (jobState === 'queued' || jobState === 'running') {
      continue;
    }

    if (jobState === 'done') {
      const stdout = typeof job?.stdout === 'string' ? job.stdout : '';
      const stderr = typeof job?.stderr === 'string' ? job.stderr : '';
      const finishedAt = typeof job?.finishedAt === 'string' ? job.finishedAt : nowIso();
      const promptAt = resolveTranscriptPromptAt({
        pendingAt: p?.at,
        jobStartedAt: job?.startedAt,
        finishedAt,
      });
      if (jobKind === 'codex') {
        const parsed = parseCodexJobTranscript(job);
        const turnModel =
          normalizeChatModel(parsed.model) ??
          pendingModel ??
          (await readCodexLastTurnModel({
            runtime,
            containerName,
            threadId: String(parsed.threadId ?? entry?.codexThreadId ?? ''),
          }).catch(() => null));
        const threadId = parsed.threadId;
        const msg = parsed.message;
        const output = String(msg ?? '').trimEnd();
        if (!output) {
          const error = formatTranscriptJobFailure({
            agentId: jobKind,
            stdoutRaw: stdout,
            stderrRaw: stderr,
            fallbackRaw: 'codex finished but no message was parsed',
            exitCode: 0,
          });
          pendingList[i] = { ...p, state: 'failed', error, observability: undefined, blipClones: undefined, updatedAt: nowIso() };
          changed = true;
          continue;
        }
        if (threadId) {
          entry.codexThreadId = threadId;
          changed = true;
        }
        // Record transcript turn (success).
        turns.push({
          at: promptAt,
          promptAt,
          completedAt: finishedAt,
          id,
          prompt: String(p?.prompt ?? ''),
          ...(turnModel ? { model: turnModel } : {}),
          ...(promptAttachments.length > 0 ? { attachments: promptAttachments } : {}),
          ...(promptAutomation ? { automation: promptAutomation } : {}),
          ok: true,
          output,
        });
        transcriptIds.add(id);
        completedTurnIdsForSnapshot.push(id);
        pendingList[i] = { ...p, state: 'sent', observability: undefined, blipClones: undefined, updatedAt: nowIso() };
        changed = true;
        continue;
      }

      if (jobKind === 'pi') {
        const parsed = parsePiJobTranscript(job);
        const turnModel = normalizeChatModel(parsed.model) ?? pendingModel;
        if (parsed.sessionId && String(parsed.sessionId).trim() && String(entry?.piSessionId ?? '').trim() !== parsed.sessionId) {
          entry.piSessionId = parsed.sessionId;
          changed = true;
        }
        const output = String(parsed.message ?? '').trimEnd();
        if (!output) {
          pendingList[i] = { ...p, state: 'failed', error: 'pi finished but no assistant message was parsed', observability: undefined, blipClones: undefined, updatedAt: nowIso() };
          changed = true;
          continue;
        }
        turns.push({
          at: promptAt,
          promptAt,
          completedAt: finishedAt,
          id,
          prompt: String(p?.prompt ?? ''),
          ...(turnModel ? { model: turnModel } : {}),
          ...(promptAttachments.length > 0 ? { attachments: promptAttachments } : {}),
          ...(promptAutomation ? { automation: promptAutomation } : {}),
          ok: true,
          output,
        });
        transcriptIds.add(id);
        completedTurnIdsForSnapshot.push(id);
        pendingList[i] = { ...p, state: 'sent', observability: undefined, blipClones: undefined, updatedAt: nowIso() };
        changed = true;
        continue;
      }

      if (jobKind === 'blip') {
        const parsed = parseBlipJobTranscript(job);
        const turnModel = normalizeChatModel(parsed.model) ?? pendingModel;
        if (parsed.sessionId && String(parsed.sessionId).trim() && String(entry?.blipSessionId ?? '').trim() !== parsed.sessionId) {
          entry.blipSessionId = parsed.sessionId;
          changed = true;
        }
        const output = String(parsed.message ?? '').trimEnd();
        if (!output) {
          pendingList[i] = { ...p, state: 'failed', error: 'blip finished but no assistant message was parsed', observability: undefined, blipClones: undefined, updatedAt: nowIso() };
          changed = true;
          continue;
        }
        turns.push({
          at: promptAt,
          promptAt,
          completedAt: finishedAt,
          id,
          prompt: String(p?.prompt ?? ''),
          ...(turnModel ? { model: turnModel } : {}),
          ...(promptAttachments.length > 0 ? { attachments: promptAttachments } : {}),
          ...(promptAutomation ? { automation: promptAutomation } : {}),
          ok: true,
          output,
        });
        transcriptIds.add(id);
        pendingList[i] = { ...p, state: 'sent', observability: undefined, blipClones: undefined, updatedAt: nowIso() };
        changed = true;
        continue;
      }

      if (
        jobKind === 'opencode' &&
        !(typeof entry?.openCodeSessionId === 'string' && String(entry.openCodeSessionId).trim())
      ) {
        // Best-effort: discover session id after first successful run, so future turns
        // can continue the exact same OpenCode session.
        const openCodeSessionId =
          (await ensureOpenCodeSessionId({
            droneId,
            droneLabel: String(d?.name ?? '').trim() || droneId,
            containerName: String(d?.containerName ?? d?.name ?? droneId).trim() || droneId,
            chatName: opts.chatName,
          }).catch(() => null)) ?? null;
        if (openCodeSessionId) {
          entry.openCodeSessionId = openCodeSessionId;
          changed = true;
        }
      }

      // Non-Codex builtins: treat stdout as final output.
      const output = (stdout || stderr || '').trimEnd();
      turns.push({
        at: promptAt,
        promptAt,
        completedAt: finishedAt,
        id,
        prompt: String(p?.prompt ?? ''),
        ...(pendingModel ? { model: pendingModel } : {}),
        ...(promptAttachments.length > 0 ? { attachments: promptAttachments } : {}),
        ...(promptAutomation ? { automation: promptAutomation } : {}),
        ok: true,
        output: output || '(no output)',
      });
      transcriptIds.add(id);
      completedTurnIdsForSnapshot.push(id);
      pendingList[i] = { ...p, state: 'sent', observability: undefined, blipClones: undefined, updatedAt: nowIso() };
      changed = true;
      continue;
    }

    if (jobState === 'failed') {
      if (jobKind === 'codex') {
        const stdout = String(job?.stdout ?? '');
        const stderr = String(job?.stderr ?? '');
        const parsed = parseCodexJobTranscript(job);
        const turnModel =
          normalizeChatModel(parsed.model) ??
          pendingModel ??
          (await readCodexLastTurnModel({
            runtime,
            containerName,
            threadId: String(parsed.threadId ?? entry?.codexThreadId ?? ''),
          }).catch(() => null));
        const output = String(parsed.message ?? '').trimEnd();
        const finishedAt = typeof job?.finishedAt === 'string' ? job.finishedAt : nowIso();
        const promptAt = resolveTranscriptPromptAt({
          pendingAt: p?.at,
          jobStartedAt: job?.startedAt,
          finishedAt,
        });
        // Self-heal false failed states only when Codex emitted a terminal
        // completion event. An in-flight status update is not a final answer.
        const terminalEvent = String(parsed.terminalEvent ?? '').trim();
        const hasCompletedTurn = terminalEvent === 'turn.completed' || terminalEvent === 'response.completed';
        if (output && hasCompletedTurn) {
          if (parsed.threadId) {
            entry.codexThreadId = parsed.threadId;
            changed = true;
          }
          turns.push({
            at: promptAt,
            promptAt,
            completedAt: finishedAt,
            id,
            prompt: String(p?.prompt ?? ''),
            ...(turnModel ? { model: turnModel } : {}),
            ...(promptAttachments.length > 0 ? { attachments: promptAttachments } : {}),
            ...(promptAutomation ? { automation: promptAutomation } : {}),
            ok: true,
            output,
          });
          transcriptIds.add(id);
          completedTurnIdsForSnapshot.push(id);
          pendingList[i] = { ...p, state: 'sent', error: undefined, observability: undefined, blipClones: undefined, updatedAt: nowIso() };
          changed = true;
          continue;
        }
      }
      if (jobKind === 'pi') {
        const stdout = String(job?.stdout ?? '');
        const parsed = parsePiJobTranscript(job);
        const turnModel = normalizeChatModel(parsed.model) ?? pendingModel;
        const output = String(parsed.message ?? '').trimEnd();
        const finishedAt = typeof job?.finishedAt === 'string' ? job.finishedAt : nowIso();
        const promptAt = resolveTranscriptPromptAt({
          pendingAt: p?.at,
          jobStartedAt: job?.startedAt,
          finishedAt,
        });
        if (parsed.sessionId && String(parsed.sessionId).trim() && String(entry?.piSessionId ?? '').trim() !== parsed.sessionId) {
          entry.piSessionId = parsed.sessionId;
          changed = true;
        }
        // Same self-heal logic as Codex: if Pi produced a complete assistant turn before the
        // daemon finalized the job as failed, trust the parsed transcript output.
        if (output) {
          turns.push({
            at: promptAt,
            promptAt,
            completedAt: finishedAt,
            id,
            prompt: String(p?.prompt ?? ''),
            ...(turnModel ? { model: turnModel } : {}),
            ...(promptAttachments.length > 0 ? { attachments: promptAttachments } : {}),
            ...(promptAutomation ? { automation: promptAutomation } : {}),
            ok: true,
            output,
          });
          transcriptIds.add(id);
          completedTurnIdsForSnapshot.push(id);
          pendingList[i] = { ...p, state: 'sent', error: undefined, observability: undefined, blipClones: undefined, updatedAt: nowIso() };
          changed = true;
          continue;
        }
      }
      if (jobKind === 'blip') {
        const parsed = parseBlipJobTranscript(job);
        const turnModel = normalizeChatModel(parsed.model) ?? pendingModel;
        const output = String(parsed.message ?? '').trimEnd();
        const finishedAt = typeof job?.finishedAt === 'string' ? job.finishedAt : nowIso();
        const promptAt = resolveTranscriptPromptAt({
          pendingAt: p?.at,
          jobStartedAt: job?.startedAt,
          finishedAt,
        });
        if (parsed.sessionId && String(parsed.sessionId).trim() && String(entry?.blipSessionId ?? '').trim() !== parsed.sessionId) {
          entry.blipSessionId = parsed.sessionId;
          changed = true;
        }
        if (output && parsed.terminalEvent === 'session_finished') {
          turns.push({
            at: promptAt,
            promptAt,
            completedAt: finishedAt,
            id,
            prompt: String(p?.prompt ?? ''),
            ...(turnModel ? { model: turnModel } : {}),
            ...(promptAttachments.length > 0 ? { attachments: promptAttachments } : {}),
            ...(promptAutomation ? { automation: promptAutomation } : {}),
            ok: true,
            output,
          });
          transcriptIds.add(id);
          pendingList[i] = { ...p, state: 'sent', error: undefined, observability: undefined, blipClones: undefined, updatedAt: nowIso() };
          changed = true;
          continue;
        }
      }
      const exitCode =
        typeof job?.exitCode === 'number' && Number.isFinite(job.exitCode)
          ? Math.floor(job.exitCode)
          : null;
      let errText = formatTranscriptJobFailure({
        agentId: jobKind,
        stdoutRaw: String(job?.stdout ?? ''),
        stderrRaw: String(job?.stderr ?? ''),
        fallbackRaw:
          String(job?.error ?? '').trim() ||
          String(job?.stderr ?? '').trim() ||
          String(job?.stdout ?? '').trim() ||
          '',
        exitCode,
      });
      pendingList[i] = { ...p, state: 'failed', error: errText, observability: undefined, blipClones: undefined, updatedAt: nowIso() };
      changed = true;
      continue;
    }

    if (jobState === 'canceled') {
      pendingList[i] = { ...p, state: 'failed', error: STOPPED_BY_USER_ERROR, observability: undefined, blipClones: undefined, updatedAt: nowIso() };
      changed = true;
      continue;
    }
  }

  const reconciledPendingList = [...pendingList];
  const prunedPendingList = pruneCompletedPendingPrompts(pendingList as PendingPrompt[], turns, {
    keepRecentlyCompleted: true,
  });
  if (prunedPendingList.length !== pendingList.length) {
    pendingList.length = 0;
    pendingList.push(...prunedPendingList);
    changed = true;
  }

  if (changed) {
    const metadataSet: Record<string, string> = {};
    for (const field of Object.keys(metadataBefore)) {
      const value = String((entry as any)?.[field] ?? '').trim();
      if (value && value !== metadataBefore[field]) metadataSet[field] = value;
    }
    const newTurns = turns.filter((turn: any) => {
      const id = String(turn?.id ?? '').trim();
      return id && !initialTurnIds.has(id);
    });
    if (Object.keys(metadataSet).length > 0 || newTurns.length > 0) {
      await applyChatReconciliationInStore({
        droneId,
        chatName,
        metadataPatch: Object.keys(metadataSet).length > 0 ? { set: metadataSet } : undefined,
        turns: newTurns,
      });
      await projectCanonicalChatToRegistry(droneId, chatName);
    }
    for (const pending of reconciledPendingList) {
      const id = String((pending as any)?.id ?? '').trim();
      if (!id || pendingBefore.get(id) === JSON.stringify(pending)) continue;
      // Prompt delivery state has one owner. Chat reconciliation projects its
      // result into the prompt queue and never stores it in chat metadata.
      // eslint-disable-next-line no-await-in-loop
      await updatePendingPrompt({
        droneId,
        chatName,
        id,
        patch: {
          state: pending.state,
          error: pending.error,
          observability: pending.observability,
          blipClones: pending.blipClones,
          updatedAt: pending.updatedAt,
        },
      });
    }
  }

  for (const promptId of completedTurnIdsForSnapshot) {
    try {
      // eslint-disable-next-line no-await-in-loop
      await maybeStartDockerSnapshotForTranscriptTurn({ droneId, chatName, promptId });
    } catch (error: any) {
      hubLog('warn', 'failed starting docker snapshot for transcript turn', {
        droneId,
        chatName,
        promptId,
        error: String(error?.message ?? error ?? 'unknown error'),
      });
    }
  }

  if (changed) {
    // Best-effort: session ids may have been established (codexThreadId/openCodeSessionId/piSessionId/blipSessionId)
    // or a prior prompt may have completed/failed, unblocking queued follow-ups.
    enqueuePendingPromptPump(droneId, chatName);
  }

  if (chatHasReconcilablePendingPrompts({ pendingPrompts: pendingList, turns })) {
    scheduleReconcileRetry(droneId, chatName);
  } else {
    clearScheduledReconcileRetryByKey(droneChatMapKey(droneId, chatName));
  }

  void processPendingAgentCopilotTurns({ droneId, chatName }).catch((error: any) => {
    hubLog('warn', 'agent copilot scan failed after reconcile', {
      droneId,
      chatName,
      error: String(error?.message ?? error ?? 'unknown error'),
    });
  });
  void processPendingAgentMessageAutoContinueTurns({ droneId, chatName }).catch((error: any) => {
    hubLog('warn', 'agent message auto-continue scan failed after reconcile', {
      droneId,
      chatName,
      error: String(error?.message ?? error ?? 'unknown error'),
    });
  });
}

async function enqueuePrompt(opts: {
  id?: string;
  droneId: string;
  chatName: string;
  prompt: string;
  attachments?: ChatImageAttachment[];
  automation?: PromptAutomationMeta | null;
  cwd?: string | null;
  submittedAt?: string | null;
  waitForDaemonMs?: number;
  deliveryMode?: 'background' | 'immediate';
  mark?: (name: string) => void;
}): Promise<{ id: string; pendingState: PendingPromptState; blockedByAutomation: boolean }> {
  const preferredIdRaw = typeof opts.id === 'string' ? opts.id.trim() : '';
  if (preferredIdRaw && !isSafePromptId(preferredIdRaw)) {
    throw new Error('invalid promptId');
  }
  const id = preferredIdRaw || crypto.randomBytes(9).toString('hex');
  const at = normalizeSubmittedAtIso(opts.submittedAt);
  const chatName = normalizeChatName(opts.chatName);
  const droneId = normalizeDroneIdentity(opts.droneId);
  if (!droneId) throw new Error('missing droneId');

  // Make sure chat exists before we write pending state.
  await ensureChatEntry({ droneId, chatName });
  opts.mark?.('ensureChat');
  const { d, chat } = await getChatEntry({ droneId, chatName });
  const canonicalPendingPrompts = await readPendingPrompts({ droneId, chatName });
  const runtime = droneRuntime(d);
  const configuredModel = normalizeChatModel((chat as any)?.model);
  const disposition = getPromptEnqueueDisposition({
    droneId,
    chatName,
    droneEntry: d,
    chatEntry: { ...chat, pendingPrompts: canonicalPendingPrompts },
    automation: opts.automation,
  });
  const { defer, blockedByAutomation } = disposition;
  opts.mark?.('disposition');

  const cwd = normalizeDroneCwdForRuntime(d, typeof opts.cwd === 'string' ? opts.cwd : null);
  const rawAttachments = Array.isArray(opts.attachments) ? opts.attachments : [];
  const attachmentsStorageRoot = chatAttachmentsStorageRootForDrone(d);
  const attachmentsForPending = buildChatImageAttachmentRefs({
    attachments: rawAttachments,
    cwd,
    chatName,
    promptId: id,
    storageRoot: attachmentsStorageRoot,
  });

  await pushPendingPrompt({
    droneId,
    chatName,
    pending: {
      id,
      at,
      prompt: opts.prompt,
      ...(configuredModel ? { model: configuredModel } : {}),
      cwd: opts.cwd ?? null,
      ...(attachmentsForPending.length > 0 ? { attachments: attachmentsForPending } : {}),
      ...(opts.automation ? { automation: normalizePromptAutomationMeta(opts.automation) } : {}),
      ...(blockedByAutomation ? { blockedByAutomation: true } : {}),
      state: defer || opts.deliveryMode === 'background' ? 'queued' : 'sending',
      updatedAt: at,
    },
  });
  opts.mark?.('persistPending');

  if (defer || opts.deliveryMode === 'background') {
    if (rawAttachments.length > 0 && attachmentsForPending.length > 0) {
      const attachmentsDir = buildChatAttachmentsDirectory({
        cwd,
        chatName,
        promptId: id,
        storageRoot: attachmentsStorageRoot,
      });
      try {
        if (runtime === 'host') {
          await copyChatAttachmentsToHost({
            hostDir: attachmentsDir,
            attachments: rawAttachments,
          });
        } else {
          const containerName = String((d as any)?.containerName ?? (d as any)?.name ?? droneId).trim() || droneId;
          await copyChatAttachmentsToContainer({
            containerName,
            containerDir: attachmentsDir,
            attachments: rawAttachments,
          });
        }
        opts.mark?.('attachments');
      } catch (e: any) {
        const errText = e?.message ?? String(e);
        await updatePendingPrompt({
          droneId,
          chatName,
          id,
          patch: { state: 'failed', error: `failed staging queued attachments: ${errText}` },
        });
        throw new Error(`failed staging queued attachments: ${errText}`);
      }
    }
    // Persisted as queued; the background pump will claim it when the chat is deliverable.
    enqueuePendingPromptPump(droneId, chatName);
    opts.mark?.('queuePump');
    return { id, pendingState: 'queued', blockedByAutomation };
  }

  try {
    const enqueueTimeoutMs = Math.max(
      defaultPromptEnqueueTimeoutMs(),
      (typeof opts.waitForDaemonMs === 'number' && Number.isFinite(opts.waitForDaemonMs) ? Math.floor(opts.waitForDaemonMs) : 0) +
        30_000,
    );
    // Enqueue work in the drone daemon (restart-resumable).
    // eslint-disable-next-line no-await-in-loop
    const r: any = await withTimeout(
      sendPromptToChat({
        id,
        droneId,
        chatName,
        prompt: opts.prompt,
        attachments: rawAttachments,
        cwd: opts.cwd ?? null,
        waitForDaemonMs: opts.waitForDaemonMs,
        skipManagedRepoSync: Boolean(opts.automation && String((opts.automation as any)?.kind ?? '').trim() === 'prompt-loop'),
        mark: opts.mark,
      }),
      enqueueTimeoutMs,
      `prompt enqueue failed for ${droneId}/${chatName}`,
    );
    opts.mark?.('daemonEnqueue');
    if (r?.turnOk === false) {
      await updatePendingPrompt({
        droneId,
        chatName,
        id,
        patch: { state: 'failed', error: String(r?.error ?? 'failed') },
      });
    } else {
      await updatePendingPrompt({ droneId, chatName, id, patch: { state: 'sent' } });
      enqueueReconcile(droneId, chatName);
    }
    opts.mark?.('persistDelivery');
  } catch (e: any) {
    const errorText = e?.message ?? String(e);
    const diagnostics =
      looksLikeTransientPromptEnqueueError(errorText) || looksLikeContainerPausedError(errorText)
        ? await collectDroneRuntimeDiagnostics({ droneId, droneEntry: d }).catch((error) => ({ diagnosticError: compactDiagnosticError(error) }))
        : null;
    hubLog('warn', 'prompt enqueue delivery failed', {
      droneId,
      chatName,
      promptId: id,
      deliveryMode: opts.deliveryMode ?? 'immediate',
      error: errorText,
      ...(diagnostics ? { diagnostics } : {}),
    });
    if (looksLikeTransientPromptEnqueueError(errorText)) {
      const retry = await retryPendingPrompt({
        droneId,
        chatName,
        id,
        error: interruptedPromptDeliveryError(errorText),
      });
      if (retry.disposition === 'retry') {
        const nextMs = retry.nextAttemptAt ? Date.parse(retry.nextAttemptAt) : NaN;
        schedulePendingPromptPumpRetry(
          droneId,
          chatName,
          Number.isFinite(nextMs) ? Math.max(1_000, nextMs - Date.now()) : undefined,
        );
      }
    } else {
      await updatePendingPrompt({
        droneId,
        chatName,
        id,
        patch: { state: 'failed', error: errorText },
      });
    }
  }

  // Best-effort: if there are any deferred follow-ups, try to enqueue now.
  enqueuePendingPromptPump(droneId, chatName);
  return { id, pendingState: 'sending', blockedByAutomation };
}

type PromptEnqueueDisposition = {
  defer: boolean;
  blockedByAutomation: boolean;
  hasPriorActive: boolean;
  hasPriorQueued: boolean;
  waitingForSession: boolean;
};

function getPromptEnqueueDisposition(opts: {
  droneId: string;
  chatName: string;
  droneEntry: any;
  chatEntry: any;
  automation?: PromptAutomationMeta | null;
}): PromptEnqueueDisposition {
  const droneId = normalizeDroneIdentity(opts.droneId);
  const chatName = normalizeChatName(opts.chatName);
  const agent = inferChatAgent(opts.chatEntry, opts.droneEntry);
  const turns: any[] = Array.isArray((opts.chatEntry as any)?.turns) ? (opts.chatEntry as any).turns : [];
  const transcriptDoneIds = new Set(turns.map((t: any) => String(t?.id ?? '').trim()).filter(Boolean));
  const priorPending: any[] = Array.isArray((opts.chatEntry as any)?.pendingPrompts) ? (opts.chatEntry as any).pendingPrompts : [];
  const sessionKnown = agent.kind !== 'builtin' ? true : hasKnownBuiltinTranscriptSession(opts.chatEntry, agent.id);
  const automationLane = getPromptAutomationLane(droneId, chatName);
  const automationLaneBusy = promptAutomationLaneBusy(automationLane, { includeQueued: true });
  const isAutomationPrompt = Boolean(opts.automation && String((opts.automation as any)?.kind ?? '').trim() === 'prompt-loop');
  const blockedByAutomation = automationLaneBusy && !isAutomationPrompt;
  const hasPriorActive = !isAutomationPrompt
    ? hasActivePriorPendingPrompt({
        priorPendingPrompts: priorPending
          .map((p: any) => ({ id: String(p?.id ?? '').trim(), state: String(p?.state ?? '') }))
          .filter((p: any) => p.id),
        transcriptDoneIds,
      })
    : false;
  const hasPriorQueued = priorPending.some((p: any) => {
    if (String(p?.state ?? '') !== 'queued') return false;
    if (isAutomationPrompt) return !Boolean((p as any)?.blockedByAutomation);
    return true;
  });
  const waitingForSession =
    agent.kind === 'builtin'
      ? shouldDeferQueuedTranscriptPrompt({
          agentId: agent.id,
          sessionKnown,
          priorPendingPrompts: priorPending
            .map((p: any) => ({ id: String(p?.id ?? '').trim(), state: String(p?.state ?? '') }))
            .filter((p: any) => p.id),
          transcriptDoneIds,
        })
      : false;
  return {
    defer: blockedByAutomation || hasPriorActive || hasPriorQueued || waitingForSession,
    blockedByAutomation,
    hasPriorActive,
    hasPriorQueued,
    waitingForSession,
  };
}

function describePromptEnqueueConflict(disposition: PromptEnqueueDisposition): string {
  if (disposition.blockedByAutomation) return 'message would be queued behind automation';
  if (disposition.hasPriorActive || disposition.waitingForSession) return 'chat already has a pending message awaiting a response';
  if (disposition.hasPriorQueued) return 'chat already has a queued message';
  return 'message would be queued';
}

type UnifiedPromptCreateOpts = {
  group?: string | null;
  repoPath?: string | null;
  build?: boolean;
  containerPort?: number | null;
};

async function createOrEnqueuePromptUnified(opts: {
  id?: string;
  droneId: string;
  chatName: string;
  prompt: string;
  attachments?: ChatImageAttachment[];
  automation?: PromptAutomationMeta | null;
  cwd?: string | null;
  submittedAt?: string | null;
  allowQueued?: boolean;
  mark?: (name: string) => void;
}): Promise<
  | { kind: 'enqueued'; id: string; pendingState: PendingPromptState; blockedByAutomation: boolean }
  | { kind: 'error'; status: number; error: string }
> {
  const droneId = normalizeDroneIdentity(opts.droneId);
  const chatName = normalizeChatName(String(opts.chatName ?? '').trim() || 'default');
  const prompt = String(opts.prompt ?? '').trim();
  const attachments = Array.isArray(opts.attachments) ? opts.attachments : [];
  const preferredIdRaw = typeof opts.id === 'string' ? opts.id.trim() : '';
  if (preferredIdRaw && !isSafePromptId(preferredIdRaw)) {
    return { kind: 'error', status: 400, error: 'invalid promptId' };
  }
  const fallbackId = preferredIdRaw || crypto.randomBytes(9).toString('hex');

  if (!droneId) return { kind: 'error', status: 400, error: 'missing drone id' };
  if (!prompt) return { kind: 'error', status: 400, error: 'missing prompt' };

  const isAutomationPrompt = Boolean(opts.automation && String((opts.automation as any)?.kind ?? '').trim() === 'prompt-loop');
  let regSnap: any = await loadRegistry();
  opts.mark?.('loadRegistry');
  if (opts.allowQueued === false && regSnap?.pending?.[droneId] && !regSnap?.drones?.[droneId]) {
    regSnap = await loadRegistry();
    opts.mark?.('reloadRegistry');
  }
  if (regSnap?.drones?.[droneId]) {
    let liveDroneEntry = regSnap?.drones?.[droneId] ?? null;
    if (!liveDroneEntry) return { kind: 'error', status: 404, error: `unknown drone: ${droneId}` };
    let chatEntry = liveDroneEntry?.chats?.[chatName] ?? null;
    if (chatHasActiveDockerSnapshot(chatEntry)) {
      await failStaleDockerSnapshotsForChat({ droneId, chatName });
      opts.mark?.('snapshotMaintenance');
      regSnap = await loadRegistry();
      opts.mark?.('reloadRegistry');
      liveDroneEntry = regSnap?.drones?.[droneId] ?? null;
      if (!liveDroneEntry) return { kind: 'error', status: 404, error: `unknown drone: ${droneId}` };
      chatEntry = liveDroneEntry?.chats?.[chatName] ?? null;
    }
    if (chatHasActiveDockerSnapshot(chatEntry)) {
      return {
        kind: 'error',
        status: 409,
        error: 'Docker snapshot is in progress for this chat; wait for it to finish before sending another message',
      };
    }
    if (opts.allowQueued === false) {
      const disposition = getPromptEnqueueDisposition({
        droneId,
        chatName,
        droneEntry: liveDroneEntry,
        chatEntry,
        automation: opts.automation,
      });
      if (disposition.defer) {
        return {
          kind: 'error',
          status: 409,
          error: `${describePromptEnqueueConflict(disposition)}; fleet send requires immediate delivery`,
        };
      }
    }
    const r = await enqueuePrompt({
      id: fallbackId,
      droneId,
      chatName,
      prompt,
      attachments,
      automation: opts.automation,
      cwd: opts.cwd ?? null,
      submittedAt: opts.submittedAt ?? null,
      deliveryMode: opts.allowQueued === false || isAutomationPrompt ? 'immediate' : 'background',
      mark: opts.mark,
    });
    return {
      kind: 'enqueued',
      id: r.id,
      pendingState: r.pendingState,
      blockedByAutomation: r.blockedByAutomation,
    };
  }

  // If the drone is still provisioning, stage prompt rows on the pending entry and
  // migrate them into normal chat `pendingPrompts` once startup finishes.
  if (regSnap?.pending?.[droneId] && !regSnap?.drones?.[droneId]) {
    if (opts.allowQueued === false) {
      return {
        kind: 'error',
        status: 409,
        error: `drone "${droneId}" is still starting; fleet send requires immediate delivery`,
      };
    }
    if (attachments.length > 0) {
      return {
        kind: 'error',
        status: 409,
        error: `drone "${droneId}" is still starting (attachments require an active drone)`,
      };
    }
    const submittedAt = normalizeSubmittedAtIso(opts.submittedAt);
    const queuedPending: PendingPrompt = {
      id: fallbackId,
      at: submittedAt,
      prompt,
      ...(opts.cwd != null ? { cwd: opts.cwd } : {}),
      state: 'queued',
      updatedAt: submittedAt,
    };
    const queuedStatus = await pushPendingStartupPrompt({ droneId, chatName, pending: queuedPending });
    if (queuedStatus === 'active') {
      const r = await enqueuePrompt({
        id: fallbackId,
        droneId,
        chatName,
        prompt,
        attachments,
        automation: opts.automation ?? null,
        cwd: opts.cwd ?? null,
        submittedAt: opts.submittedAt ?? null,
        deliveryMode: isAutomationPrompt ? 'immediate' : 'background',
        mark: opts.mark,
      });
      return {
        kind: 'enqueued',
        id: r.id,
        pendingState: r.pendingState,
        blockedByAutomation: r.blockedByAutomation,
      };
    }
    if (queuedStatus !== 'queued') {
      return { kind: 'error', status: 404, error: `unknown drone: ${droneId}` };
    }
    return {
      kind: 'enqueued',
      id: fallbackId,
      pendingState: 'queued',
      blockedByAutomation: false,
    };
  }
  return { kind: 'error', status: 404, error: `unknown drone: ${droneId}` };
}

